INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',47,'{"_type":"chat:Message","id":"8641420749:124","threadId":"telegram:8641420749","text":"J’ai senti les genoux mais pas de douleur. Des que je me deconcentre, que je regarde trop ailleurs, que je pedale à une main, que je check mon téléphone, ça devient un poil douloureux. Mais si je suis concentré et consciencieux sur la position du genou en tournant la jambe, tout va bien.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"J’ai senti les genoux mais pas de douleur. Des que je me deconcentre, que je regarde trop ailleurs, que je pedale à une main, que je check mon téléphone, ça devient un poil douloureux. Mais si je suis concentré et consciencieux sur la position du genou en tournant la jambe, tout va bien.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":289,"offset":288}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":289,"offset":288}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":289,"offset":288}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-17T10:03:30.000Z","edited":false},"attachments":[],"isMention":false}',1782295409232);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',48,'{"_type":"chat:Message","id":"8641420749:127","threadId":"telegram:8641420749","text":"J’ai fait un massage des jambes aujourdhui, c’est une masseuse qui fait de la medecine chinoise, elle me connait bien, mon historique et mon profil. Elle a bien insisté sur la jambe gauche, là ou ca fait mal. Sur les deux jambes en general","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"J’ai fait un massage des jambes aujourdhui, c’est une masseuse qui fait de la medecine chinoise, elle me connait bien, mon historique et mon profil. Elle a bien insisté sur la jambe gauche, là ou ca fait mal. Sur les deux jambes en general","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":240,"offset":239}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":240,"offset":239}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":240,"offset":239}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-17T15:44:18.000Z","edited":false},"attachments":[],"isMention":false}',1782315858482);
