INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',51,'{"_type":"chat:Message","id":"8641420749:139","threadId":"telegram:8641420749","text":"Soyons realistes, je ne ferai jamais plus de 1000m de piscine. Je déteste ça. Tu peux checker mon historique Strava de natation tu verras.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Soyons realistes, je ne ferai jamais plus de 1000m de piscine. Je déteste ça. Tu peux checker mon historique Strava de natation tu verras.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":139,"offset":138}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":139,"offset":138}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":139,"offset":138}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-18T16:40:31.000Z","edited":false},"attachments":[],"isMention":false}',1782405631691);
