INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',71,'{"_type":"chat:Message","id":"8641420749:198","threadId":"telegram:8641420749","text":"Genoux très bien hier pendant la séance, douleur 0/10. Mais j’ai légèrement senti le genou gauche hier dans l’après-midi, douleur 2/10. Je crois que c’est passé ce matin","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Genoux très bien hier pendant la séance, douleur 0/10. Mais j’ai légèrement senti le genou gauche hier dans l’après-midi, douleur 2/10. Je crois que c’est passé ce matin","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":170,"offset":169}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":170,"offset":169}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":170,"offset":169}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-21T05:29:29.000Z","edited":false},"attachments":[],"isMention":false}',1782624568986);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',72,'{"_type":"chat:Message","id":"8641420749:202","threadId":"telegram:8641420749","text":"Let’s also start tracking how long I slept. In general I need 8 hours of sleep to be feeling good. Below that I start accumulating sleep debt. Above that is bonus. \nToday I slept 9h","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Let’s also start tracking how long I slept. In general I need 8 hours of sleep to be feeling good. Below that I start accumulating sleep debt. Above that is bonus.\nToday I slept 9h","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":17,"offset":181}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":17,"offset":181}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":17,"offset":181}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-21T07:38:30.000Z","edited":false},"attachments":[],"isMention":false}',1782632309119);
