INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',86,'{"_type":"chat:Message","id":"8641420749:257","threadId":"telegram:8641420749","text":"Pas de douleurs, leger ressenti, mais surement du au fait que j’ai dea chaussures pas du tout adaptées.\nOn adapte le plan pour le reste de la semaine vu ce que j’ai fait jusqu’à aujourd’hui ou on ne change rien ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Pas de douleurs, leger ressenti, mais surement du au fait que j’ai dea chaussures pas du tout adaptées.\nOn adapte le plan pour le reste de la semaine vu ce que j’ai fait jusqu’à aujourd’hui ou on ne change rien ?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":109,"offset":212}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":109,"offset":212}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":109,"offset":212}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-23T20:41:44.000Z","edited":false},"attachments":[],"isMention":false}',1782852103834);
