INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',388,'{"_type":"chat:Message","id":"-5124234082:2349","threadId":"telegram:-5124234082","text":"Hi Pepa,\nI would like to revise your algorithm for meal planning. I think we need to tweak a bit the priorities and weights of each constraints you take into account. Overall the meal planning has been valuable, and we used it. Thanks a lot for that. But I have the following feelings on which we can improve:\n- you have been suggesting too often very similar recipes (the pois chiches/feta based kinda recipes for example, or panados too often)\n- you have been suggesting too often too simplistic recipes and even sometimes options which don’t compose a normal full meal (once you proposed « riz + feijao branco », this is not a meal…)\n- the batch cooking suggestion are too simplistic and usually don’t suit us (e.g preparing frango desfiado) - we ended up never doing it except the soup. \n- you very rarely went into the recipe list and proposed a full new recipe from this list.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Hi Pepa,\nI would like to revise your algorithm for meal planning. I think we need to tweak a bit the priorities and weights of each constraints you take into account. Overall the meal planning has been valuable, and we used it. Thanks a lot for that. But I have the following feelings on which we can improve:","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":301,"offset":309}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":301,"offset":309}}},{"type":"list","ordered":false,"start":null,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"you have been suggesting too often very similar recipes (the pois chiches/feta based kinda recipes for example, or panados too often)","position":{"start":{"line":3,"column":3,"offset":312},"end":{"line":3,"column":136,"offset":445}}}],"position":{"start":{"line":3,"column":3,"offset":312},"end":{"line":3,"column":136,"offset":445}}}],"position":{"start":{"line":3,"column":1,"offset":310},"end":{"line":3,"column":136,"offset":445}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"you have been suggesting too often too simplistic recipes and even sometimes options which don’t compose a normal full meal (once you proposed « riz + feijao branco », this is not a meal…)","position":{"start":{"line":4,"column":3,"offset":448},"end":{"line":4,"column":191,"offset":636}}}],"position":{"start":{"line":4,"column":3,"offset":448},"end":{"line":4,"column":191,"offset":636}}}],"position":{"start":{"line":4,"column":1,"offset":446},"end":{"line":4,"column":191,"offset":636}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"the batch cooking suggestion are too simplistic and usually don’t suit us (e.g preparing frango desfiado) - we ended up never doing it except the soup.","position":{"start":{"line":5,"column":3,"offset":639},"end":{"line":5,"column":154,"offset":790}}}],"position":{"start":{"line":5,"column":3,"offset":639},"end":{"line":5,"column":155,"offset":791}}}],"position":{"start":{"line":5,"column":1,"offset":637},"end":{"line":5,"column":155,"offset":791}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"you very rarely went into the recipe list and proposed a full new recipe from this list.","position":{"start":{"line":6,"column":3,"offset":794},"end":{"line":6,"column":91,"offset":882}}}],"position":{"start":{"line":6,"column":3,"offset":794},"end":{"line":6,"column":91,"offset":882}}}],"position":{"start":{"line":6,"column":1,"offset":792},"end":{"line":6,"column":91,"offset":882}}}],"position":{"start":{"line":3,"column":1,"offset":310},"end":{"line":6,"column":91,"offset":882}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":6,"column":91,"offset":882}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-25T09:06:46.000Z","edited":false},"attachments":[],"isMention":false}',1782983205095);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',389,'{"_type":"chat:Message","id":"-5124234082:2352","threadId":"telegram:-5124234082","text":"Comment tu organises tes md files pour toute cette logique ? Montre moi la file structure. \nEt decris exactement ce que tu as changé based on my feedback, pourquoi tu l’as changé et quel effet ça va avoir","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Comment tu organises tes md files pour toute cette logique ? Montre moi la file structure.\nEt decris exactement ce que tu as changé based on my feedback, pourquoi tu l’as changé et quel effet ça va avoir","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":113,"offset":204}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":113,"offset":204}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":113,"offset":204}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-25T09:11:50.000Z","edited":false},"attachments":[],"isMention":false}',1782983509453);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',390,'{"_type":"chat:Message","id":"-5124234082:2355","threadId":"telegram:-5124234082","text":"Le log doit se baser sur ton plan : si on dit rien, c’est qu’on a suivi ton plan. Sinon, on te dira ce qu’on a fait.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Le log doit se baser sur ton plan : si on dit rien, c’est qu’on a suivi ton plan. Sinon, on te dira ce qu’on a fait.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":117,"offset":116}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":117,"offset":116}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":117,"offset":116}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-25T09:22:53.000Z","edited":false},"attachments":[],"isMention":false}',1782984173444);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',391,'{"_type":"chat:Message","id":"-5124234082:2358","threadId":"telegram:-5124234082","text":"Ok, maintenant je veux que tu analyse toute la logique qui existe et intervient lors du planning/suggestions de recettes. Tu dois evaluer la complexité de toute cette logique, evaluer s’il y a besoin de separer dans autant de .md files differentes (il en faut plus ? On peut faire avec moins de files ?), evaluer si certaines parties de la logique sont trop isolées et risque d’etre skipé. enfin propose des changements si c’est necessaire. \nL’objectif overarching est de simplifier la logique si besoin pour garantir un meal planning optimal sans complexité inutile.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Ok, maintenant je veux que tu analyse toute la logique qui existe et intervient lors du planning/suggestions de recettes. Tu dois evaluer la complexité de toute cette logique, evaluer s’il y a besoin de separer dans autant de .md files differentes (il en faut plus ? On peut faire avec moins de files ?), evaluer si certaines parties de la logique sont trop isolées et risque d’etre skipé. enfin propose des changements si c’est necessaire.\nL’objectif overarching est de simplifier la logique si besoin pour garantir un meal planning optimal sans complexité inutile.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":126,"offset":567}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":126,"offset":567}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":126,"offset":567}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-25T09:26:58.000Z","edited":false},"attachments":[],"isMention":false}',1782984418449);
