INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',404,'{"_type":"chat:Message","id":"-5124234082:2395","threadId":"telegram:-5124234082","text":"Hier on discutait du plan, tu proposais:\n\n**Jeu 25**\nDéj : Soupe + **Salade de pâtes thon mayo maison** ← nouvelle, jamais proposée\nDîner : Soupe + **Pollo chipotle** + riz ← batch chain\n\n**Ven 26**\nDéj : Soupe + Salade lentilles avocat feta (avocats basket)\nDîner : Soupe + **Pad Thai poulet** ← complète batch chain\n\n**Sam 27**\nDéj : Soupe + **Alubias puerros miso** (poireau basket + haricots + miso)\nDîner : Soupe + Robalo al forno + poivron + tomates rôtis (recette à écrire ce soir)\n\n**Dim 28**\nDéj : Soupe + Pasta con tomate fresco y ajo (tomates basket)\nDîner : Soupe + **Ensalada lentejas pimientos feta caramelizada**\n\nRecettes nouvelles de la bibliothèque : 5 sur 8 jamais utilisées. Un seul plat légumineuses-feta (vs 3 avant).\n\nBatch : soupe ce soir + pollo chipotle ×6 vendredi soir.\n\n\nEt je repondais :\n\nOn les a toutes deja faites dans les dernières semaines. Tu n’as pas bien gardé l’historique peut etre. \nInfo en plus : on a 24 oeufs, il faut absolument qu’on les consomme","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Hier on discutait du plan, tu proposais:","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":41,"offset":40}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":41,"offset":40}}},{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Jeu 25","position":{"start":{"line":3,"column":3,"offset":44},"end":{"line":3,"column":9,"offset":50}}}],"position":{"start":{"line":3,"column":1,"offset":42},"end":{"line":3,"column":11,"offset":52}}},{"type":"text","value":"\nDéj : Soupe + ","position":{"start":{"line":3,"column":11,"offset":52},"end":{"line":4,"column":15,"offset":67}}},{"type":"strong","children":[{"type":"text","value":"Salade 