INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',406,'{"_type":"chat:Message","id":"-5124234082:2400","threadId":"telegram:-5124234082","text":"Ce midi on a mangé dehors. \nJe vais faire des oeufs et des pommes de terre sautees ce soir. Donne moi recette pommes de terres sautees. Elles sont deja cuites a l’eau","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Ce midi on a mangé dehors.\nJe vais faire des oeufs et des pommes de terre sautees ce soir. Donne moi recette pommes de terres sautees. Elles sont deja cuites a l’eau","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":139,"offset":166}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":139,"offset":166}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":139,"offset":166}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-26T18:02:20.000Z","edited":false},"attachments":[],"isMention":false}',1783101738606);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',106,'{"_type":"chat:Message","id":"8641420749:298","threadId":"telegram:8641420749","text":"Aqui vem o script completo da consulta com o osteopata. \n\nSummarize it, analyse it.\n\n\n\n\ncomo está tudo bem bicicleta como está. \n\nbem mas tive umas coisas para contar. Não sei se se lembra exatamente mas posso fazer um short backup Tenho 10 anos de experiência com síndrome feromo patelar p à esquerda então estava a ver agora ainda se vê desequilíbrio muscular. O ano passado nos vimos depois duma prova de 1300 km M-N que se inflamou o joelho à esquerda e depois tratei com o Bernardo e duas vezes consigo e depois tudo otimo. Não fui super regular no esforço desde fevereiro/ março claramente, mas pronto consegui até aumentar as distâncias fiz até 370 no mesmo dia. Então foi mesmo um ano muito bom. Tive uma prova de 850 km há cinco semanas que era três dias. E no primeiro dia era pra fazer 380. saída meia-noite. E o problema é que estive doente, tipo, constipado, durante 4-5 semanas antes. Não conseguia recuperar não conseguia não conseguia. E então os 10 dias antes parei tudo. tendo que concent energia a recuperar. Só que parei tudo, mesmo tudo. E o meu corpo depois de uma noite para andar no primeiro dia diz não. E aconteceu uma coisa que nunca me tinha acontecido sempre tento gerir bem os joelhos mas posso ter umas pequenas inflamacoes, consigo saber bem como chegar até o fim. Só que desta vez inflamo a esquerda muito rapidamente. Ou seja, em 2h00 depois de 130km parei e não conseguia mais dobrar a perna depois de meia hora parado. Então diz pronto. acabou já desisti deixei o meu amigo sair deprimi todo o resto do dia. Só que à noite, quando fui pro hotel onde ela estava, já conseguia pedalar tranquilo ate o hotel. O dia seguinte, depois de 9h00 a dormir, zero a dor. Então já arranquei outra vez mais para brincar do que para competir. E então acabei com ele até fiz o Mont Ventoux no terceiro dia, quase sem dor ok últimos 50 km estava um pouquinho coisa de dor mas nada grace. Mas foi uma inflamacao super rápida e desinflamou super rápido também que pra mim foi uma surpresa eu nunca tinha acontecido isso. E pronto é por isso que estou aqui desde então estou muito focado na recuperação nas últimas duas semanas. \n\nEsta prova foi quando? \n\nHá cinco semanas, às três semanas seguintes. tinha algumas coisas previstas uma viagem de bicicleta com as. crianças pronto não foi super focado na recuperação mas não fiz nada maluco. E pronto aqui estou agora a planejar uma prova fim de setembro e é isso. \n\nComo é que é a prova? \n\nÉ a mesma que ano passado são 1300 mas é mais tranquilo são 220 30 por dia não é. \n\nQual é o objetivo?\n\nÉ acabar com zero dor esse objetivo.\n\nOk esse objetivo nao é nada bom. \n\nna verdade que não é bem o objetivo. Eu vou com dois amigos que eu nunca vejo e um objetivo é ter um melhor momento de amizade não é \n\nSe fores por esse objetivo, bastas a probabilidade da dor.\n\nMas os meus amigos também não tão tão preparado como eu então acho que o ritmo vai ser um pouco mais tranquilo vai ser mais tranquilo. E pronto.\n\nO facto de teres vivido tanto tempo com aquele conflito à esquerda programou um pensamento de não dor que no fundo é um pensamento de dor mas que na questão de não ter. Mas a dor. realidade estás a vida. Já tiveste mais do que tive bem para perceberes. Nas provas tu sempre é modo gerir para que esteja. Eu creio que essa dor que tiveste no joelho, ainda por cima do lado esquerdo, que é o lado emocional em termos de angústia, e o que é que isso foi um disparo de tensão física que eu receio daqueles 10 dias será que eu vou conseguir será que eu não vou conseguir.\n\nÉ bom ouvir isso é a primeira vez.\n\nIsso é passado. Liberta-te. Como é que foi este ano?\n\nEste ano foi ótimo. Menos esta constipação que depois impactou a prova foi um ano otimo. Fiz um Porto Lisboa também 18h00 na bicicleta zero dor tudo perfeito. \n\nOu seja, eu quero que tu comes-me a explicar as coisas no sentido o resto da história.. O que viste, o que saboaste, momentos do que não não dor. Porque parece que o troféu que tu ganhas no fim é o não dor. Não é bom. energia não é boa.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Aqui vem o script completo da consulta com o osteopata.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":56,"offset":55}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":57,"offset":56}}},{"type":"paragraph","children":[{"type":"text","value":"Summarize it, analyse it.","position":{"start":{"line":3,"column":1,"offset":58},"end":{"line":3,"column":26,"offset":83}}}],"position":{"start":{"line":3,"column":1,"offset":58},"end":{"line":3,"column":26,"offset":83}}},{"type":"paragraph","children":[{"type":"text","value":"como está tudo bem bicicleta como está.","position":{"start":{"line":8,"column":1,"offset":88},"end":{"line":8,"column":40,"offset":127}}}],"position":{"start":{"line":8,"column":1,"offset":88},"end":{"line":8,"column":41,"offset":128}}},{"type":"paragraph","children":[{"type":"text","value":"bem mas tive umas coisas para contar. Não sei se se lembra exatamente mas posso fazer um short backup Tenho 10 anos de experiência com síndrome feromo patelar p à esquerda então estava a ver agora ainda se vê desequilíbrio muscular. O ano passado nos vimos depois duma prova de 1300 km M-N que se inflamou o joelho à esquerda e depois tratei com o Bernardo e duas vezes consigo e depois tudo otimo. Não fui super regular no esforço desde fevereiro/ março claramente, mas pronto consegui até aumentar as distâncias fiz até 370 no mesmo dia. Então foi mesmo um ano muito bom. Tive uma prova de 850 km há cinco semanas que era três dias. E no primeiro dia era pra fazer 380. saída meia-noite. E o problema é que estive doente, tipo, constipado, durante 4-5 semanas antes. Não conseguia recuperar não conseguia não conseguia. E então os 10 dias antes parei tudo. tendo que concent energia a recuperar. Só que parei tudo, mesmo tudo. E o meu corpo depois de uma noite para andar no primeiro dia diz não. E aconteceu uma coisa que nunca me tinha acontecido sempre tento gerir bem os joelhos mas posso ter umas pequenas inflamacoes, consigo saber bem como chegar até o fim. Só que desta vez inflamo a esquerda muito rapidamente. Ou seja, em 2h00 depois de 130km parei e não conseguia mais dobrar a perna depois de meia hora parado. Então diz pronto. acabou já desisti deixei o meu amigo sair deprimi todo o resto do dia. Só que à noite, quando fui pro hotel onde ela estava, já conseguia pedalar tranquilo ate o hotel. O dia seguinte, depois de 9h00 a dormir, zero a dor. Então já arranquei outra vez mais para brincar do que para competir. E então acabei com ele até fiz o Mont Ventoux no terceiro dia, quase sem dor ok últimos 50 km estava um pouquinho coisa de dor mas nada grace. Mas foi uma inflamacao super rápida e desinflamou super rápido também que pra mim foi uma surpresa eu nunca tinha acontecido isso. E pronto é por isso que estou aqui desde então estou muito focado na recuperação nas últimas duas semanas.","position":{"start":{"line":10,"column":1,"offset":130},"end":{"line":10,"column":2015,"offset":2144}}}],"position":{"start":{"line":10,"column":1,"offset":130},"end":{"line":10,"column":2016,"offset":2145}}},{"type":"paragraph","children":[{"type":"text","value":"Esta prova foi quando?","position":{"start":{"line":12,"column":1,"offset":2147},"end":{"line":12,"column":23,"offset":2169}}}],"position":{"start":{"line":12,"column":1,"offset":2147},"end":{"line":12,"column":24,"offset":2170}}},{"type":"paragraph","children":[{"type":"text","value":"Há cinco semanas, às três semanas seguintes. tinha algumas coisas previstas uma viagem de bicicleta com as. crianças pronto não foi super focado na recuperação mas não fiz nada maluco. E pronto aqui estou agora a planejar uma prova fim de setembro e é isso.","position":{"start":{"line":14,"column":1,"offset":2172},"end":{"line":14,"column":258,"offset":2429}}}],"position":{"start":{"line":14,"column":1,"offset":2172},"end":{"line":14,"column":259,"offset":2430}}},{"type":"paragraph","children":[{"type":"text","value":"Como é que é a prova?","position":{"start":{"line":16,"column":1,"offset":2432},"end":{"line":16,"column":22,"offset":2453}}}],"position":{"start":{"line":16,"column":1,"offset":2432},"end":{"line":16,"column":23,"offset":2454}}},{"type":"paragraph","children":[{"type":"text","value":"É a mesma que ano passado são 1300 mas é mais tranquilo são 220 30 por dia não é.","position":{"start":{"line":18,"column":1,"offset":2456},"end":{"line":18,"column":82,"offset":2537}}}],"position":{"start":{"line":18,"column":1,"offset":2456},"end":{"line":18,"column":83,"offset":2538}}},{"type":"paragraph","children":[{"type":"text","value":"Qual é o objetivo?","position":{"start":{"line":20,"column":1,"offset":2540},"end":{"line":20,"column":19,"offset":2558}}}],"position":{"start":{"line":20,"column":1,"offset":2540},"end":{"line":20,"column":19,"offset":2558}}},{"type":"paragraph","children":[{"type":"text","value":"É acabar com zero dor esse objetivo.","position":{"start":{"line":22,"column":1,"offset":2560},"end":{"line":22,"column":37,"offset":2596}}}],"position":{"start":{"line":22,"column":1,"offset":2560},"end":{"line":22,"column":37,"offset":2596}}},{"type":"paragraph","children":[{"type":"text","value":"Ok esse objetivo nao é nada bom.","position":{"start":{"line":24,"column":1,"offset":2598},"end":{"line":24,"column":33,"offset":2630}}}],"position":{"start":{"line":24,"column":1,"offset":2598},"end":{"line":24,"column":34,"offset":2631}}},{"type":"paragraph","children":[{"type":"text","value":"na verdade que não é bem o objetivo. Eu vou com dois amigos que eu nunca vejo e um objetivo é ter um melhor momento de amizade não é","position":{"start":{"line":26,"column":1,"offset":2633},"end":{"line":26,"column":133,"offset":2765}}}],"position":{"start":{"line":26,"column":1,"offset":2633},"end":{"line":26,"column":134,"offset":2766}}},{"type":"paragraph","children":[{"type":"text","value":"Se fores por esse objetivo, bastas a probabilidade da dor.","position":{"start":{"line":28,"column":1,"offset":2768},"end":{"line":28,"column":59,"offset":2826}}}],"position":{"start":{"line":28,"column":1,"offset":2768},"end":{"line":28,"column":59,"offset":2826}}},{"type":"paragraph","children":[{"type":"text","value":"Mas os meus amigos também não tão tão preparado como eu então acho que o ritmo vai ser um pouco mais tranquilo vai ser mais tranquilo. E pronto.","position":{"start":{"line":30,"column":1,"offset":2828},"end":{"line":30,"column":145,"offset":2972}}}],"position":{"start":{"line":30,"column":1,"offset":2828},"end":{"line":30,"column":145,"offset":2972}}},{"type":"paragraph","children":[{"type":"text","value":"O facto de teres vivido tanto tempo com aquele conflito à esquerda programou um pensamento de não dor que no fundo é um pensamento de dor mas que na questão de não ter. Mas a dor. realidade estás a vida. Já tiveste mais do que tive bem para perceberes. Nas provas tu sempre é modo gerir para que esteja. Eu creio que essa dor que tiveste no joelho, ainda por cima do lado esquerdo, que é o lado emocional em termos de angústia, e o que é que isso foi um disparo de tensão física que eu receio daqueles 10 dias será que eu vou conseguir será que eu não vou conseguir.","position":{"start":{"line":32,"column":1,"offset":2974},"end":{"line":32,"column":567,"offset":3540}}}],"position":{"start":{"line":32,"column":1,"offset":2974},"end":{"line":32,"column":567,"offset":3540}}},{"type":"paragraph","children":[{"type":"text","value":"É bom ouvir isso é a primeira vez.","position":{"start":{"line":34,"column":1,"offset":3542},"end":{"line":34,"column":35,"offset":3576}}}],"position":{"start":{"line":34,"column":1,"offset":3542},"end":{"line":34,"column":35,"offset":3576}}},{"type":"paragraph","children":[{"type":"text","value":"Isso é passado. Liberta-te. Como é que foi este ano?","position":{"start":{"line":36,"column":1,"offset":3578},"end":{"line":36,"column":53,"offset":3630}}}],"position":{"start":{"line":36,"column":1,"offset":3578},"end":{"line":36,"column":53,"offset":3630}}},{"type":"paragraph","children":[{"type":"text","value":"Este ano foi ótimo. Menos esta constipação que depois impactou a prova foi um ano otimo. Fiz um Porto Lisboa também 18h00 na bicicleta zero dor tudo perfeito.","position":{"start":{"line":38,"column":1,"offset":3632},"end":{"line":38,"column":159,"offset":3790}}}],"position":{"start":{"line":38,"column":1,"offset":3632},"end":{"line":38,"column":160,"offset":3791}}},{"type":"paragraph","children":[{"type":"text","value":"Ou seja, eu quero que tu comes-me a explicar as coisas no sentido o resto da história.. O que viste, o que saboaste, momentos do que não não dor. Porque parece que o troféu que tu ganhas no fim é o não dor. Não é bom. energia não é boa.","position":{"start":{"line":40,"column":1,"offset":3793},"end":{"line":40,"column":237,"offset":4029}}}],"position":{"start":{"line":40,"column":1,"offset":3793},"end":{"line":40,"column":237,"offset":4029}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":40,"column":237,"offset":4029}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-06-26T22:58:40.000Z","edited":false},"attachments":[],"isMention":false}',1783119520848);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',107,'{"_type":"chat:Message","id":"8641420749:299","threadId":"telegram:8641420749","text":"Na verdade, como tu isso assim, aqui nós os amigos e tal mas lá dentro está. \n\nAqui tu permiste. lá dentro estava. Estamos a falar abertamente com vibração plena. Mudamos o objetivo. Ou seja, e este foi condicionado, a minha observação foi condicionada pelo que tu falaste para setembro. Não, eu quero fazer uma prova sem dor. Isso é uma estupidez. Dor é normal. Dor é normal. Dor é normal. Dor é normal. Dor é normal. Dor é normal. Dor é normal. dor sente mal. Sim. E o corpo fala e diz, esta dor não é para existir. Esta dor podes continuar. Esta dor só precisas de soltar o músculo, esta dor só precisas disso. Se tiveres muito bloqueado a dor, se tivermos bloqueados não conseguimos interpretar. E ficamos só síndrome fêmero praar que foi Aquele teatro negro que vivês durante 10 anos. Isso é passado filho. Vamos fazer um pequeno exercício. Tô-te a falar com moral. Sim porque não estou-te a falar com a primeira vez que te conheces estamos a falar com uma ação uma ação e reação ou seja com provas dadas com factos. Vamos fazer aqui um bocadinho exercício mental. Só tens que deixar isto. Em breve, uma coisinha leve. Fecha os teus olhos. Recua o passado E deixa que te venha a memória ou da memória que te venha o momento ou uma realidade que tenhas vivido. Desespero relativamente às dores eu ajudo. Vem alguma coisa? \n\nSim. \n\nQueres descrevê-lo como se tivesse vivido agora. \n\nBem primeiro vem o primeiro trauma porque não estava nada pedalado nada a sério os meus amigos me trazeram naquilo de fazer 110 km estava de fixa E claramente ao largo do dia estive mais dólar e até não sei 15 km no fim era impossível andar e continuei e puxei e cheguei mas eu também destruído. \n\nE Como é que te sentes ao lembrar isso como é que achas que te sentiste na altura no final, durante e no final. Qual é o sentimento que vem? \n\nAgora olhar para trás é que é estupidez não ter parado. Só porque estava com os amigo Na altura era uma dor que nunca tinha vivido o fato de não saber que não podia e ir apertar esse pedal novamente. \n\nVai ao momento principal que está mais claro na tua mente. Sim. E vê o que te vem em termos de interpretação. Como é que achas que tu te sentiste contigo. \n\nNão sei foi a seguir a outros\n\nSentiste revolta depois disso. Por teres feito isso por ter pelo comportamento julgaste-te.\n\nNão eu senti-me fraco e não dá vamos. \n\nConsegues sentir isso neste momento sentir essa sensação. Revivendo essa falso. Consegues sentir esse momento. Como é que te faz sentido reviver. \n\nSim voltava atrás parávamos também olhando para trás não acho que foi um trauma tão grave assim nunca depois fiz tudo mal a seguir também. Parei de pedalar, parei o desporto e foi círculo vicioso de uma coisa não ajudava a outra que não ajuda, erros. \n\nErros exatamente. Quem foi a responsabilidade \n\nfoi só eu. \n\nQuanto tempo é que tu te culpaste? \n\nHá 10 anos desde então. Mas pronto também vejo isso muito hoje como uma aprendizagem. \n\nE hoje como é que está o teu estado de culpa. Interpreta avalio pergunta-te sempre\n\nEu acho que tá o porque eu vejo muitas coisas como aprendizagens. E o que eu faço este ano o que fiz é tantas aprendizagem destes anos todos. Claro são 10 anos também porque eu fiz outras coisas mas poderia ser três anos mas se voltar a cometer erros. Fiz alguns erros na hora a ir talvez a começar essa prova eu podia ter sabido que não ia dar e todos os sinais diziam não vai dar. Até esqueci o bib para ir. Mas depois o poder voltar ao segundo dia e eu tercer dia foi uma alegria imensa. Mas é verdade que to sempre em modo conservador \n\nÉ como nós com os nossos filhos eles andam a brincar e nós Brinca à vontade mas olha cuidado com isto, olha cuidado com aquilo ou seja me tá a brincar mas está a levar com aquilo. Em vez be free. \n\nEu sou muito mais a segundo o pai, be free. As pessoas no parque vem me dizer ah o sou filho esta a fazer isso e eu ah sim sim pode deixar.. Mas comigo eu sou muito mais  controlador\n\nporque passaste por um trauma.\n\n Sim eu acho que sim acho que é uma coisa minha eu estou sempre a controlar muitas coisas.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Na verdade, como tu isso assim, aqui nós os amigos e tal mas lá dentro está.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":77,"offset":76}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":78,"offset":77}}},{"type":"paragraph","children":[{"type":"text","value":"Aqui tu permiste. lá dentro estava. Estamos a falar abertamente com vibração plena. Mudamos o objetivo. Ou seja, e este foi condicionado, a minha observação foi condicionada pelo que tu falaste para setembro. Não, eu quero fazer uma prova sem dor. Isso é uma estupidez. Dor é normal. Dor é normal. Dor é normal. Dor é normal. Dor é normal. Dor é normal. Dor é normal. dor sente mal. Sim. E o corpo fala e diz, esta dor não é para existir. Esta dor podes continuar. Esta dor só precisas de soltar o músculo, esta dor só precisas disso. Se tiveres muito bloqueado a dor, se tivermos bloqueados não conseguimos interpretar. E ficamos só síndrome fêmero praar que foi Aquele teatro negro que vivês durante 10 anos. Isso é passado filho. Vamos fazer um pequeno exercício. Tô-te a falar com moral. Sim porque não estou-te a falar com a primeira vez que te conheces estamos a falar com uma ação uma ação e reação ou seja com provas dadas com factos. Vamos fazer aqui um bocadinho exercício mental. Só tens que deixar isto. Em breve, uma coisinha leve. Fecha os teus olhos. Recua o passado E deixa que te venha a memória ou da memória que te venha o momento ou uma realidade que tenhas vivido. Desespero relativamente às dores eu ajudo. Vem alguma coisa?","position":{"start":{"line":3,"column":1,"offset":79},"end