INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',111,'{"_type":"chat:Message","id":"8641420749:303","threadId":"telegram:8641420749","text":"Que mais razao tens para dazer ultra cycling?\n\nPronto agora as próximas são mais superficiais eu sempre fiz desporto de Não sei como se diz em português. Tipo surf skate, Snowboard coisas de ride. \n\nE adrenalina. \n\nSim mas ao mesmo tempo sou um pouco medidoso. Nunca fui o maluco do skate. mas eu encontro essas sensações mesmas sensações do surf skate ou Snoword na bicicleta. É como uma extensão do meu corpo Essas são razões mais superficiais e a aventura estar na natureza é uma coisa que eu adoro adoro. \n\nÉ uma teoria minha, não é estudada. Mais uma vez, agarrando-me nisto, eu defendo ou argumento a teoria dos sete corpos, que são 10. Aquela mais válida para mim são os sete corpos. Sete corpos são sete elementos que nos. Temos o corpo físico, o primário, depois temos o corpo energético, na Geral Chinos, as marridianas, os sacras, depois temos o campo mental e inferior. Mental superior, emocional, sentimental. Por quê? Porque é o sentimento e a emoção que dá coro ao pensamento. O pensamento pode ser neutro, sem importância mas se mete a uma emoção de de medo. tar no escuro pode ser uma coisa normal mas tens medo do escuro é um medo que entra e transforma a coisa e te cria outras coisas. Mental superior é 12345 uns cinco corpos não? E depois tens o leu superior, o leu intuitivo desculpa pois o leu superior. Certo, depois tens outros três. Jamais pouco per espírito de espírito. A vibração entre eles eles são em frequências diferentes mas tem que haver harmonia entre eles. Se eu tenho uma pessoa que é em termos no corpo mental muito ativo, muito forte, essa pessoa tendencialmente vai precisar de desportos que envolvam intensidade em movimento para alinhar a vibração. \n\nEu sou over thinker\n\nPortanto, eu se te convidasse para ir caminhar eu tinha que recolher trilho forte, coisa com desafio. Se quisesse falar contigo sobre coisas mais fortes ainda, teríamos pôr o movimento. É mais difícil para ti ter esta conversa porque estás parado. Vai ao encontro disso. Eu tenho alguns amigos que para falar com eles às vezes se tivermos que falar determinado assunto ou o que seja, vamos dar uma volta.. Eu já não sou assim. sinto-me,raizo e aqui estou. passar. Mas já não é. Era. Não sou mais nenhum. Porque não sou tão racional como tenhoados perfis. E então para mim fazer movimento ou não movimenta eu não tenho paciência para muito tempo de gosto de subir climbing, o desafio de superar algo e coisas a fazer molhar sempre 380 e 40 3840 e tal. Mas é sem preparação, boa, fácil, coisa de experiência. Sou mais sensorial. Est vezes acho muito mais sensorial. E há que nos entendermos. É natural que em ti, por gosto ou por não gosto, por infância ou na infância, vais sempre procurar Long distance e com algum desafio e ch Para que consigas controlar variadas e ao mesmo tempo pôr o momento para fluir e também aliviar um pouco. Para que não te sufoque a necessidade de movimento, é importante ir trabalhando esse over. Thinking. Keep thinking trabalha o over. Disciplinas budistas ferramentas budistas para mim são das melhores. até lá. Buda queuda fez milhares técnicas meditativas. E imensas formas de. pode ser em walking, pode ser cor, pode ser parada, mas de certa forma a vida se vai pensando nisso porque a vida pode-te obrigar a parar. A vida em si. E tu não podes adoecer mentalmente energeticamente por isso. Entendes? E portanto, vai trabalhando nisso porque o teu coração um dia pode dizer calma, preciso de um tempo pra recuperar e tu podes não ter que poder fazer isto. Isto é o que acontece normalmente. Ok pois já não é joelho ou já é o coração pois já não é o coração é o rim já não é o mas já é. Mas é a patologia que te obriga a compensar. Mas continuas no mesmo plano overtinking porque agora vais fazer tudo o que possa existir pra controlar as tuas veias coronárias as tuas artérias coronárias o teu médico picário. E vais andar. Não mudas, o padrão não il luz. Não passas por um plano assim. Mantém as tuas atividades que sententes este equilibram, mas vai pensando nisto em como é que eu vou trabalhar este meu overticking.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Que mais razao tens para dazer ultra cycling?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":46,"offset":45}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":46,"offset":45}}},{"type":"paragraph","children":[{"type":"text","value":"Pronto agora as próximas são mais superficiais eu sempre fiz desporto de Não sei como se diz em português. Tipo surf skate, Snowboard coisas de ride.","position":{"start":{"line":3,"column":1,"offset":47},"end":{"line":3,"column":150,"offset":196}}}],"position":{"start":{"line":3,"column":1,"offset":47},"end":{"line":3,"column":151,"offset":197}}},{"type":"paragraph","children":[{"type":"text","value":"E adrenalina.","position":{"start":{"line":5,"column":1,"offset":199},"end":{"line":5,"column":14,"offset":212}}}],"position":{"start":{"line":5,"column":1,"offset":199},"end":{"line":5,"column":15,"offset":213}}},{"type":"paragraph","children":[{"type":"text","value":"Sim mas ao mesmo tempo sou um pouco medidoso. Nunca fui o maluco do skate. mas eu encontro essas sensações mesmas sensações do surf skate ou Snoword na bicicleta. É como uma extensão do meu corpo Essas são razões mais superficiais e a aventura estar na natureza é uma coisa que eu adoro adoro.","position":{"start":{"line":7,"column":1,"offset":215},"end":{"line":7,"column":294,"offset":508}}}],"position":{"start":{"line":7,"column":1,"offset":215},"end":{"line":7,"column":295,"offset":509}}},{"type":"paragraph","children":[{"type":"text","value":"É uma teoria minha, não é estudada. Mais uma vez, agarrando-me nisto, eu defendo ou argumento a teoria dos sete corpos, que são 10. Aquela 